use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// Random ID generated by the agent on first start. A reinstall is a new node.
pub type NodeId = Uuid;
pub type InstanceId = Uuid;

/// Monotonic per-node counter, bumped whenever that node's desired set changes.
pub type Generation = u64;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Arch {
    X86_64,
    Aarch64,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Capacity {
    pub vcpus: u32,
    pub memory_mb: u64,
    pub disk_gb: u64,
}

// ---- registration ---------------------------------------------------------

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegisterRequest {
    pub node_id: NodeId,
    pub hostname: String,
    pub arch: Arch,
    pub capacity: Capacity,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum RegistrationStatus {
    /// Known to the controller, waiting for admin approval.
    Pending,
    Approved,
    /// Admin removed this node. The agent should stop and not retry.
    Retired,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct RegisterResponse {
    pub status: RegistrationStatus,
}

// ---- desired state --------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum DesiredState {
    Running,
    Stopped,
    /// Delete: remove the VM and its boot disk, then report `Absent`.
    Absent,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct BootDisk {
    /// Platform-neutral image name, e.g. `ubuntu-24.04`.
    pub image: String,
    /// SHA-256 of the base image in kiln's catalogue for this arch. The agent
    /// fetches it from kiln by hash if missing. `None` means the node must
    /// have `<image>.img` locally, as before the catalogue existed.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub sha256: Option<String>,
    pub size_gb: u64,
}

/// Lowercase hex SHA-256, as kiln names catalogue blobs.
pub fn valid_sha256(hash: &str) -> bool {
    hash.len() == 64 && hash.bytes().all(|b| b.is_ascii_digit() || (b'a'..=b'f').contains(&b))
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Nic {
    /// VMs made before copper networks were bridged onto this host bridge,
    /// with addresses from the site's router. Empty for new VMs.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub bridge: String,
    pub mac: String,
    /// The VM's fixed address on its node's copper network, e.g.
    /// `10.42.1.10/24`. Set for every VM made since copper networks.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub address: Option<String>,
}

/// A node's part of copper's network: the /24 its VMs live in. The node is
/// the gateway, and the gateway is also the VMs' DNS server.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct NodeNetwork {
    /// `10.42.1.0/24`
    pub subnet: String,
    /// `10.42.1.1`
    pub gateway: String,
    /// All of copper's VM addresses, every node's /24 included: `10.42.0.0/16`.
    #[serde(default = "default_space")]
    pub space: String,
}

fn default_space() -> String {
    "10.42.0.0/16".into()
}

impl NodeNetwork {
    /// The second and third octets, for short names: `cu-42-1`.
    pub fn octets(&self) -> Option<(u8, u8)> {
        let mut it = self.subnet.split('/').next()?.split('.').skip(1).map(|o| o.parse::<u8>().ok());
        Some((it.next()??, it.next()??))
    }
}

/// What a node needs to wire its VMs into the rest of copper. For every
/// project with a VM on the node, every VM in that project on any node. The
/// node lets traffic into one of its VMs only from that VM's own project, and
/// its DNS answers a VM only with names from its own project.
#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct NetworkMap {
    #[serde(default)]
    pub projects: Vec<ProjectNetwork>,
}

impl NetworkMap {
    pub fn is_empty(&self) -> bool {
        self.projects.is_empty()
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ProjectNetwork {
    /// Kiln's project id. Names are only unique per owner.
    pub id: Uuid,
    /// The middle of `<vm>.<project>.copper`.
    pub name: String,
    pub vms: Vec<VmAddress>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct VmAddress {
    pub name: String,
    /// The VM's copper address alone, e.g. `10.42.3.10`.
    pub address: String,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct InstanceSpec {
    pub vcpus: u32,
    pub memory_mb: u64,
    pub arch: Arch,
    pub boot_disk: BootDisk,
    pub nics: Vec<Nic>,
    /// Authorized keys for the default user, injected through cloud-init.
    #[serde(default)]
    pub ssh_keys: Vec<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesiredInstance {
    pub id: InstanceId,
    /// User-chosen name; becomes the guest hostname.
    pub name: String,
    /// Its project's name: the guest's DNS search domain is
    /// `<project>.copper`, so other VMs in it resolve by name alone.
    #[serde(default, skip_serializing_if = "String::is_empty")]
    pub project: String,
    pub state: DesiredState,
    pub spec: InstanceSpec,
}

/// What the controller wants this node to look like. The agent persists the
/// whole thing before acting on it, so it can reconcile while disconnected.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct DesiredNodeState {
    pub generation: Generation,
    pub instances: Vec<DesiredInstance>,
    /// The node's copper network. `None` only before kiln has assigned one.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub network: Option<NodeNetwork>,
    /// Who the node's VMs may talk to and look up. A VM on another node
    /// joining or leaving one of this node's projects bumps the generation.
    #[serde(default, skip_serializing_if = "NetworkMap::is_empty")]
    pub map: NetworkMap,
}

// ---- observed state -------------------------------------------------------

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ObservedState {
    Starting,
    Running,
    Stopping,
    Stopped,
    /// Retries exhausted. `error` says why.
    Failed,
    Absent,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ObservedInstance {
    pub id: InstanceId,
    pub state: ObservedState,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub error: Option<String>,
    #[serde(default)]
    pub addresses: Vec<String>,
    /// Live resource use, when the backend can measure it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub usage: Option<Usage>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ObservedNodeState {
    /// The generation the agent was reconciling toward when it took this snapshot.
    pub generation_seen: Generation,
    pub instances: Vec<ObservedInstance>,
    pub capacity: Capacity,
    /// Live resource use of the whole host.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub usage: Option<Usage>,
    /// Whether the host side of the copper network (`copper-net.service`)
    /// is in place. Without it VMs have no internet. `None` on platforms
    /// that don't need it.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub network_ready: Option<bool>,
    /// Whether the node's subnet is live as a Tailscale subnet route, so
    /// tailnet devices reach its VMs directly. `None` without Tailscale.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub tailnet_route: Option<bool>,
}

/// A point-in-time reading. CPU is in tenths of a percent of what the thing
/// was given: an instance's vCPUs, or a node's threads.
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
pub struct Usage {
    pub cpu_permille: u32,
    pub memory_used_bytes: u64,
    pub memory_total_bytes: u64,
    pub disk_used_bytes: u64,
    pub disk_total_bytes: u64,
}

// ---- serial consoles ----------------------------------------------------------

/// Someone wants to reach a VM: its serial console, or with `port` a TCP
/// port on it (22 for `cu ssh`). The node dials back to kiln to carry it,
/// so kiln never connects to a node or a VM.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct ConsoleRequest {
    pub session: Uuid,
    pub instance: InstanceId,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub port: Option<u16>,
}

/// Why a node couldn't carry a session, such as the VM not answering yet.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct SessionRefused {
    pub reason: String,
}

/// Short, human-comparable form of a node credential: the first 16 hex
/// digits of its SHA-256, grouped. Ingot prints the same at registration, so
/// an admin can check a pending node is the machine they think it is.
pub fn fingerprint(token_sha256_hex: &str) -> String {
    let head: String = token_sha256_hex.chars().take(16).collect();
    head.as_bytes().chunks(4).map(|c| String::from_utf8_lossy(c).into_owned()).collect::<Vec<_>>().join(" ")
}

/// A single image filename stem, never a path or hidden directory component.
pub fn valid_image_name(name: &str) -> bool {
    !name.is_empty() && name.len() <= 128
        && name.as_bytes()[0].is_ascii_alphanumeric()
        && name.bytes().all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b"._-".contains(&b))
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn node_tokens_have_one_shared_validation_rule() {
        assert!(valid_node_token(&"a1".repeat(32)));
        for token in ["a".repeat(63), "a".repeat(65), "g".repeat(64), format!("{}\n", "a".repeat(63))] {
            assert!(!valid_node_token(&token));
        }
    }

    #[test]
    fn image_names_are_single_components() {
        for name in ["", ".", "..", "../nas/disk", "/etc/disk", "ubuntu/../../disk", "a\\b", "a\n", "UPPER"] {
            assert!(!valid_image_name(name), "accepted {name:?}");
        }
        for name in ["ubuntu-24.04", "debian_12", "a..b"] { assert!(valid_image_name(name)); }
    }
}

/// Enrollment credentials are generated as two random UUIDs without separators.
pub fn valid_node_token(token: &str) -> bool {
    token.len() == 64 && token.bytes().all(|b| b.is_ascii_hexdigit())
}
